            snapshotRefRepository.insert(row);
        }
    }

    /**
     * 校验通过的单条引用：携带附件元数据、脱敏版本（ORIGINAL 时为 null）与固化摘要原文。
     */
    public record ResolvedRef(
            AttachmentRefRequest ref,
            AttachmentMeta attachment,
