    public ResponseEntity<RedactionRule> registerRule(
            @RequestHeader(value = ROLE_HEADER, required = false) String roleHeader,
            @Valid @RequestBody RegisterRuleRequest request) {
        requireRole(roleHeader, ActorRole.OFFICER);
        RedactionRule rule = new RedactionRule(request.ruleCode(), request.ruleVersion(),
                request.ruleName(), false, null, Instant.now(clock));
        ruleRepository.insert(rule);
        return ResponseEntity.status(201).body(rule);
    }

    /**
     * 脱敏专员撤销规则版本登记；撤销后不可再用于新脱敏。
