        // 同附件同一规则版本重复使用：422（重新登记新规则版本给 att-3 用，确保失败原因单一）
        createRedactions("OFFICER", "obs-1", "req-v6", "batch-x6", List.of(
                        redactionItem("att-1", "PII", 1, "再来一次", "替换")))
